import yaml,glob
rows={}
for f in glob.glob('.archon-horizon/roadmap/items/*.yaml'):
    d=yaml.safe_load(open(f)); rows[d['id']]=d
act=[k for k,v in rows.items() if v.get('status')=='active']
live={'ajc-albanese','ajc-fbc','ajc-pic0av','ajc-rr','ajcr-cert-r2','ajcr-charts','ajcr-divrep','ajcr-w5-av'}
refs={}
for f in glob.glob('.archon-horizon/tasks/items/*.yaml'):
    t=yaml.safe_load(open(f))
    for r in (t.get('roadmap_refs') or []): refs.setdefault(r,[]).append((t['id'],t.get('status')))
def par(k): return (rows.get(k,{}).get('metadata') or {}).get('parent')
def held(k): return any(tid in live for tid,_ in refs.get(k,[]))
anc=set()
for k in rows:
    if held(k):
        p=par(k)
        while p:
            anc.add(p); p=par(p)
print('active:',len(act))
for k in sorted(act):
    tag='DIRECT ' if held(k) else ('ANCESTOR' if k in anc else 'ORPHAN  ')
    print(tag,k,refs.get(k,'-'))
"

